INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6501142, 965943, 15711, '<td valign="top">Thanks for actually having her smoke.  All of these entries with an unlit one just doesn''t work for that genre.  Nice lighting. She''s smoooooooth. :)</td>', 'Thanks for actually having her smoke.  All of these entries with an unlit one just doesn''t work for that genre.  Nice lighting. She''s smoooooooth. :)', '2011-08-10 21:31:48.000000', NULL, 1),
