(6501147, 966539, 15711, '<td valign="top">Love the blinds'' shadows.</td>', 'Love the blinds'' shadows.', '2011-08-10 21:34:25.000000', NULL, 1),
(6501148, 966048, 15711, '<td valign="top">Kudos for letting the gumshoe smoke.  An unlit cig just wasn''t part of the scene then.  Love the blinds and the potted plant to set the scene..</td>', 'Kudos for letting the gumshoe smoke.  An unlit cig just wasn''t part of the scene then.  Love the blinds and the potted plant to set the scene..', '2011-08-10 21:35:24.000000', NULL, 1),
(6501150, 966471, 15711, '<td valign="top">Very noir.  One of the few that really has the whole mood.  I applaud the use of real smoke because every one of those movies was filled with the stuff. LOL  I particularly love the shadows of the leaves on the brick wall.  Nice going.</td>', 'Very noir.  One of the few that really has the whole mood.  I applaud the use of real smoke because every one of those movies was filled with the stuff. LOL  I particularly love the shadows of the leaves on the brick wall.  Nice going.', '2011-08-10 21:38:31.000000', NULL, 1),
