(6503707, 966304, 96751, '<td valign="top">This is like two different images to me, each of them gorgeous on their own, but somehow, not working together.</td>', 'This is like two different images to me, each of them gorgeous on their own, but somehow, not working together.', '2011-08-14 01:57:02.000000', NULL, 1),
(6503709, 966443, 96751, '<td valign="top">Marvelous set-up.  A bit too well lit for me.  I would have liked to see the lighting drop off dramatically on the far left, and much more toned down on the wall behind her and on the right of the frame.  Wonderful shadow presence.</td>', 'Marvelous set-up.  A bit too well lit for me.  I would have liked to see the lighting drop off dramatically on the far left, and much more toned down on the wall behind her and on the right of the frame.  Wonderful shadow presence.', '2011-08-14 01:57:55.000000', NULL, 1),
(6503710, 966483, 96751, '<td valign="top">This would have made a great stripes entry!</td>', 'This would have made a great stripes entry!', '2011-08-14 01:58:10.000000', NULL, 1),
