(6503712, 966274, 96751, '<td valign="top">Nice!</td>', 'Nice!', '2011-08-14 01:58:49.000000', NULL, 1),
(6503714, 966515, 96751, '<td valign="top">I like the intensity of the shot, but find the black on the right waaaaaay to overpowering and pointless.  This could easily have been cropped to midchest from the bottom, and virtually all of the black except for the edge near his face.</td>', 'I like the intensity of the shot, but find the black on the right waaaaaay to overpowering and pointless.  This could easily have been cropped to midchest from the bottom, and virtually all of the black except for the edge near his face.', '2011-08-14 02:00:09.000000', NULL, 1),
